'use strict';
/* Bundles authored JSON into js/data/content-bundle.js so the app runs from a plain
 * <script> tag (works on GitHub Pages and from file:// on locked-down school devices).
 * Source of truth stays in /content; never edit the bundle by hand. */
const fs = require('fs');
const path = require('path');
const { loadContent } = require('./load-library.js');

const content = loadContent();
const out = '/* GENERATED by tools/build-bundle.js from /content. Do not edit by hand. */\n' +
  '(function (root) { root.WRG = root.WRG || {}; root.WRG.content = ' + JSON.stringify(content) + '; }(typeof self !== "undefined" ? self : this));\n';
const target = path.join(__dirname, '..', 'js', 'data', 'content-bundle.js');
fs.writeFileSync(target, out);
console.log('Wrote ' + path.relative(process.cwd(), target) + ' (' + out.length + ' bytes, ' + content.templates.length + ' templates)');
